import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/web%E3%81%AB%E3%82%82%E3%81%82%E3%82%8B%E3%82%88%E3%81%86%E3%81%AA%E5%86%85%E5%AE%B9%E3%81%AE%E6%9C%AC%E3%81%AE%E4%BE%A1%E5%80%A4.html","title":"webにもあるような内容の本の価値","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.41,"words":422},"filePathRelative":"webにもあるような内容の本の価値.md"}`),a={name:`webにもあるような内容の本の価値.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="webにもあるような内容の本の価値" tabindex="-1"><a class="header-anchor" href="#webにもあるような内容の本の価値"><span>webにもあるような内容の本の価値</span></a></h1><p>ブログにしようと思ったが途中になってる書きかけエッセイ。</p><h2 id="検索すれば見つかる内容の本の価値" tabindex="-1"><a class="header-anchor" href="#検索すれば見つかる内容の本の価値"><span>検索すれば見つかる内容の本の価値</span></a></h2><p>お絵描きの入門書のレビューでは、良く「webで検索すれば同じような内容の情報は見つかるので星一つ」みたいなのがある。 わざわざお金を出して買った本と同じ内容がwebで無料で見つかると、損した気持ちになるのはわからんでもないが、 本としてまとまったものが手元にある価値もあるよなぁ。</p><p>という事でwebにあるのと同じ内容の本の価値を考える。</p><h3 id="選ぶコストが不要" tabindex="-1"><a class="header-anchor" href="#選ぶコストが不要"><span>選ぶコストが不要</span></a></h3><p>まず検索して出てきたものの中から良いものを探すのは労力が掛かる。 手間だというだけでなく、ものによっては初心者が取捨選択をするのが難しい場合もある。 著者が自分の名前を出して行った取捨選択には、 ある程度の責任がともなっているので、 単にリンクを適当に羅列するよりは価値がある。</p><h3 id="ブラウズのしやすさ" tabindex="-1"><a class="header-anchor" href="#ブラウズのしやすさ"><span>ブラウズのしやすさ</span></a></h3><p>選択のコストだけではなく、まとまっている価値もある。 順番に読んでいける形式は、あたりまえだが読んでいきやすい。 単発ページがバラバラにあると、 それらの間の遷移にコストがかかる。 フローが途切れやすく、進みも悪い。</p><p>オフラインで順番に読めるのも、より集中して読むのを助けてくれる。 webは注意を散らす要因も多いので、 本である事はそれ自体にメリットがあると思う。</p><p>webの記事でも似たような形式にまとめる事はたぶん出来るが、 その労力を代わりに払ってくれているものにはお金を払う価値もあるだろう。</p><h3 id="読む計画の立てやすさ" tabindex="-1"><a class="header-anchor" href="#読む計画の立てやすさ"><span>読む計画の立てやすさ</span></a></h3><p>一冊という単位が明確で、その中の章立てにはどういった内容がどれだけ書かれているか、 という事も固定される。 まとまった内容が固定されると、計画や管理をやりやすくなる。</p><p>章だてによって、その章を読むのか読まないのか、という判断も、大きな単位でしやすい。 単発記事をいちいち判断するよりも、もう一段大きな計画を立てられる。</p><p>進捗も管理しやすい。 単発記事を3つ読んだ、よりも、Chapter 3を7割終えた、という方が、 どれだけやったか、あとどれだけやるか、という見通しも立てやすい。 どこまでも続く単発記事の海よりも、 とりあえずあと少しでこの章が終わるのでひとまずこの章の終わりまでやろう、 という方が続けるモチベーションも保ちやすい。</p><p>少しやる気が減ってきた時も、目次をながめたり先のページをパラパラ眺めたりする事で、 やる気をふたたび取り戻したりとかもやりやすい。</p><p>一冊の範囲の内容にどれだけまとまりとしての意味があるかは著者の力量次第ではあるが、 良く書かれている本ならなんらかの哲学のもとにまとめられている事が期待出来る。 ある章を終える事で得られるものに、ある程度のまとまりが期待出来る(事もある)。</p><p>今の自分に必要なものと比較して、本を選んだりその中の章を選ぶのは、 単発記事をつなげあわせていくよりも計画を立てやすい。</p><h3 id="他人のレビューが期待出来る-売れてる本なら" tabindex="-1"><a class="header-anchor" href="#他人のレビューが期待出来る-売れてる本なら"><span>他人のレビューが期待出来る(売れてる本なら)</span></a></h3><p>同じ本を読んだ人が、読み終わった時にどうなっているかを、レビューからある程度知る事が出来る。 単発記事を自分の必要に応じてつなぎあわせる場合は、 同じコンテンツ群を見た他の人がいないので、 そうした情報を得る事は難しい。 同じ内容を見た他の人の存在も、 本としてまとまっているメリットに思う。</p><p>同じような課題を持った先人がその本をやってどう思ったのか、 というのは、その本に期待出来る事をより</p><h3 id="内容が保存され固定される価値" tabindex="-1"><a class="header-anchor" href="#内容が保存され固定される価値"><span>内容が保存され固定される価値</span></a></h3><p>検索は結果が時間とともに変わっていくし、コンテンツが無くなる事もある。 電子書籍もなくなる事はたぶんあるんだろうけれど、webのコンテンツよりはずっと長生きだ。 途中で挫折したり再開したり、あとになって読みなおしたり、 と、長期にわたって付き合う事になれば、 内容が固定されている事には価値がある。</p>`,23)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};